import DesignSystem
import Domain
import SwiftUI

/// The oven slot: the Blender-rendered hero oven (`RenderedOven`), filling whatever frame it is
/// given. `OvenStage` gives it the top half of the open screen and `CoverStage` the folded cover.
/// There is no drawn fallback: the frames are generated by `scripts/blender/app_export.py` and
/// `scripts/build.sh` refuses to build without them.
struct OvenFrame: View {
    /// Text on the display, e.g. a time or "Prêt.".
    let plate: Text
    var isPlateItalic = false
    /// 0 cold, 1 fully heated. The current frames are rendered at full heat; kept for the glow
    /// layers to come.
    var heat: Double = 0.4
    /// The dish, its doneness and browning: for the baked-dish renders to come (the moulds); the
    /// trays are empty until then.
    let dish: Dish
    var dishProgress: Double = 0
    var browning: Browning = .golden
    /// 0 shut, 1 open to `openAngle`.
    var doorOpen: Double = 0
    /// False on the reveal, grade and ajar screens, where the door lies on the bottom half
    /// (`DoorPanel`): the image is cut off at the hinge.
    var showsDoor = true
    /// How far a fully open door drops, in degrees (88 lies flat; 180 hangs straight down).
    var openAngle: Double = 100

    /// On the open Duo the door follows the fold instead of `doorOpen` (`FoldEnvironment`).
    @Environment(\.hingeDoorAngle) private var hingeDoorAngle

    /// Kept clear above the oven for the header on the open screen, and below it for the
    /// caption on the cover.
    static let topBand: CGFloat = HitTarget.minimum
    static let bottomBand: CGFloat = Spacing.s4 + Spacing.s2

    var body: some View {
        Group {
            if let layout = OvenRenderLayout.shared {
                RenderedOven(
                    layout: layout,
                    angle: doorAngle,
                    plate: plate,
                    isPlateItalic: isPlateItalic,
                    cutsAtHinge: !showsDoor,
                    clipsToSlot: false,
                    alignsHingeToFold: hingeDoorAngle != nil
                )
            } else {
                // Only if the generated frames are missing (build.sh guards against it).
                Color.clear
            }
        }
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(Text("Oven", bundle: .module))
        .accessibilityValue(plate)
    }

    /// The door's angle in degrees: the hinge's on the open Duo, otherwise from `doorOpen`.
    private var doorAngle: Double {
        hingeDoorAngle ?? openAngle * min(max(doorOpen, 0), 1)
    }

    /// Where the lifted serving sits on the upper tray, in a slot of `size`: the tongs pick it
    /// up here on the way to decorating. A cupcake is ~60 mm on the 310 mm tray.
    static func servingFrame(dish: Dish, in size: CGSize, alignsHingeToFold: Bool = false) -> CGRect {
        guard let layout = OvenRenderLayout.shared else { return .zero }
        let (scale, origin) = RenderedOven.placement(layout: layout, in: size, alignsHingeToFold: alignsHingeToFold)
        let tray = layout.trayRect
        let width = tray.width * scale
        let side: CGFloat = switch dish {
        case .cupcakes: width * 0.2
        case .smallCake: width * 0.45
        case .largeCake: width * 0.6
        }
        let floorY = origin.y + tray.maxY * scale
        return CGRect(x: origin.x + tray.midX * scale - side / 2, y: floorY - side, width: side, height: side)
    }
}

